import { useMemo } from 'react';
import { useSelector } from 'react-redux';

import {
  selectPage,
  selectPageDataFilters,
  selectPageDataFiltersFromApplied,
  selectPageDefaults,
  selectPageFormPresetDataFilters,
  selectPageFormPresetRawData,
  selectPageRawData,
  selectPageVisibleFields,
} from 'redux/slices/filters/selectors';

export const usePageFilterData = (
  pageName: string | null,
  visibleFields?: string[],
) => {
  const safePageName = pageName ?? '__NO_PAGE__';

  const pageData = useSelector(selectPage(safePageName));
  const dataFilters = useSelector(selectPageDataFilters(safePageName));
  const formDataFilters = useSelector(
    selectPageFormPresetDataFilters(safePageName),
  );
  const formPresetRawData = useSelector(
    selectPageFormPresetRawData(safePageName),
  );
  const defaults = useSelector(selectPageDefaults(safePageName));
  const availableFields = useSelector(
    selectPageVisibleFields(safePageName, visibleFields),
  );
  const appliedDataFilters = useSelector(
    selectPageDataFiltersFromApplied(safePageName),
  );
  const rawData = useSelector(selectPageRawData(safePageName));

  return useMemo(
    () => ({
      pageData: pageName === null ? null : pageData,
      dataFilters,
      formDataFilters,
      formPresetRawData,
      defaults,
      availableFields,
      appliedDataFilters,
      rawData,
    }),
    [
      pageName,
      pageData,
      dataFilters,
      formDataFilters,
      formPresetRawData,
      defaults,
      availableFields,
      appliedDataFilters,
      rawData,
    ],
  );
};
